function outputFile = generateCudaReferenceFixtures(outputFile)
%GENERATECUDAREFERENCEFIXTURES Generate small NVIDIA CUDA reference data.
%   Run this function from a clean checkout on a Windows NVIDIA machine
%   after compiling CUDA. The generated MAT file is consumed by
%   CudaReferenceTest.

if nargin == 0
    outputFile = fullfile(fileparts(mfilename('fullpath')), ...
        'cuda_reference.mat');
end

matlabRoot = fileparts(fileparts(fileparts(mfilename('fullpath'))));
addpath(matlabRoot);
InitTIGRE('backend', 'cuda');

[coneImage, coneGeometry, coneAngles] = coneData();
[parallelImage, parallelGeometry, parallelAngles] = parallelData();
tvImage = reshape(single(mod(0:(10 * 9 * 7 - 1), 23)) / 23, [10 9 7]);
prior = 0.8 * tvImage;
gpuIds = GpuIds();

fixture = struct;
fixture.schemaVersion = 1;
fixture.metadata = struct( ...
    'matlabVersion', version, ...
    'computer', computer, ...
    'mexExtension', mexext, ...
    'gpuNames', {getGpuNames()});
fixture.input = struct( ...
    'coneImage', coneImage, ...
    'coneGeometry', coneGeometry, ...
    'coneAngles', coneAngles, ...
    'parallelImage', parallelImage, ...
    'parallelGeometry', parallelGeometry, ...
    'parallelAngles', parallelAngles, ...
    'tvImage', tvImage, ...
    'prior', prior);

coneInterpolated = Ax( ...
    coneImage, coneGeometry, coneAngles, 'interpolated', 'gpuids', gpuIds);
parallelInterpolated = Ax( ...
    parallelImage, parallelGeometry, parallelAngles, ...
    'interpolated', 'gpuids', gpuIds);
fixture.cuda = struct( ...
    'coneInterpolated', coneInterpolated, ...
    'coneSiddon', Ax( ...
        coneImage, coneGeometry, coneAngles, 'Siddon', 'gpuids', gpuIds), ...
    'coneFdk', Atb( ...
        coneInterpolated, coneGeometry, coneAngles, 'FDK', 'gpuids', gpuIds), ...
    'coneMatched', Atb( ...
        coneInterpolated, coneGeometry, coneAngles, ...
        'matched', 'gpuids', gpuIds), ...
    'parallelInterpolated', parallelInterpolated, ...
    'parallelSiddon', Ax( ...
        parallelImage, parallelGeometry, parallelAngles, ...
        'Siddon', 'gpuids', gpuIds), ...
    'parallelAtb', Atb( ...
        parallelInterpolated, parallelGeometry, parallelAngles, ...
        'FDK', 'gpuids', gpuIds), ...
    'minTv', minimizeTV(tvImage, 0.05, 2, 'gpuids', gpuIds), ...
    'adaptiveTv', minimizeAwTV( ...
        tvImage, 0.05, 2, -0.01, 'gpuids', gpuIds), ...
    'denoised', im3DDenoise( ...
        tvImage, 'TV', 2, 15, 'gpuids', gpuIds), ...
    'piccs', minimizeTV_prior( ...
        tvImage, prior, 0.05, 2, 0.5, 'gpuids', gpuIds));

save(outputFile, 'fixture', '-v7');
fprintf('CUDA reference fixture written to %s\n', outputFile);
end

function [image, geometry, angles] = coneData()
geometry = fixtureGeometry([10; 9; 7], [12; 10], 'cone');
angles = linspace(0, 2 * pi, 5);
angles(end) = [];
image = fixturePhantom(geometry.nVoxel);
end

function [image, geometry, angles] = parallelData()
geometry = fixtureGeometry([11; 9; 7], [13; 7], 'parallel');
angles = linspace(0, 2 * pi, 5);
angles(end) = [];
image = fixturePhantom(geometry.nVoxel);
end

function geometry = fixtureGeometry(nVoxel, nDetector, mode)
geometry = defaultGeometry( ...
    'nVoxel', nVoxel, 'nDetector', nDetector, 'mode', mode);
geometry.nVoxel = double(nVoxel);
geometry.nDetector = double(nDetector);
geometry.sVoxel = double(nVoxel);
geometry.dVoxel = geometry.sVoxel ./ geometry.nVoxel;
geometry.dDetector = [1; 1];
geometry.sDetector = geometry.nDetector .* geometry.dDetector;
geometry.DSO = 40;
geometry.DSD = 60;
geometry.accuracy = 0.5;
end

function image = fixturePhantom(dimensions)
[x, y, z] = ndgrid( ...
    linspace(-1, 1, dimensions(1)), ...
    linspace(-1, 1, dimensions(2)), ...
    linspace(-1, 1, dimensions(3)));
image = single((x.^2 + 1.2 * y.^2 + 0.8 * z.^2) < 0.55);
end
